(function () {
  'use strict';

  var root = document.documentElement;
  var body = document.body;
  // Links generated by the script are absolute, so they stay valid after
  // in-page navigation to a page in another directory.
  var docsRoot = new URL(body.getAttribute('data-root') || './', window.location.href).href;
  var items = window.sidebarItems || [];
  var state = { group: body.getAttribute('data-group') || '', module: body.getAttribute('data-module') || '' };

  function get(kind, key) {
    try { return window[kind].getItem(key); } catch (e) { return null; }
  }
  function set(kind, key, value) {
    try { window[kind].setItem(key, value); } catch (e) { /* ignore */ }
  }
  function escapeHtml(s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  function pageUrl(dir, slug) { return docsRoot + dir + '/' + slug + '.html'; }

  var realmTitles = { server: 'Server-side', client: 'Client-side', shared: 'Shared (server and client)' };
  // The colour-coded realm pill, as rendered on the pages.
  function realmPill(realm) {
    if (!realmTitles[realm]) return '';
    return '<span class="realm realm-' + realm + '" title="' + realmTitles[realm] + '">' + realm + '</span>';
  }
  // The compact realm dot used in the sidebar.
  function realmDot(realm) {
    if (!realmTitles[realm]) return '';
    return '<span class="realm-dot realm-dot-' + realm + '" title="' + realmTitles[realm] + '"></span>';
  }

  // Night mode -------------------------------------------------------------

  function currentTheme() {
    var setTheme = root.getAttribute('data-theme');
    if (setTheme) return setTheme;
    return window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
  }
  var themeToggle = document.querySelector('.theme-toggle');
  if (themeToggle) {
    themeToggle.addEventListener('click', function () {
      var next = currentTheme() === 'dark' ? 'light' : 'dark';
      root.setAttribute('data-theme', next);
      set('localStorage', 'fdoc-theme', next);
    });
  }

  // Sidebar ----------------------------------------------------------------

  var sidebar = document.getElementById('sidebar');
  var nav = document.getElementById('sidebar-nav');
  var tabs = document.getElementById('sidebar-tabs');
  var openGroups = {};
  try { openGroups = JSON.parse(get('sessionStorage', 'fdoc-open-groups') || '{}'); } catch (e) { openGroups = {}; }
  var currentTab = -1;

  function sectionOf(groupDir) {
    for (var i = 0; i < items.length; i++) {
      for (var j = 0; j < items[i].g.length; j++) {
        if (items[i].g[j].d === groupDir) return i;
      }
    }
    return -1;
  }

  function moduleHtml(group, m) {
    return '<li class="sidebar-item sidebar-module" data-group="' + escapeHtml(group.d) + '" data-module="' + escapeHtml(m.s) + '">' +
      '<div class="sidebar-row"><a href="' + escapeHtml(pageUrl(group.d, m.s)) + '">' + escapeHtml(m.t) + '</a></div></li>';
  }

  function renderTabs() {
    if (!tabs) return;
    tabs.innerHTML = items.map(function (section, i) {
      return '<button type="button" role="tab" data-tab="' + i + '">' + escapeHtml(section.t) + '</button>';
    }).join('');
    tabs.addEventListener('click', function (e) {
      var button = e.target.closest('button[data-tab]');
      if (button) showTab(parseInt(button.getAttribute('data-tab'), 10), true);
    });
  }

  function showTab(index, remember) {
    if (!nav || !items[index] || index === currentTab) return;
    currentTab = index;
    Array.prototype.forEach.call(tabs.querySelectorAll('button'), function (b, i) {
      b.classList.toggle('active', i === index);
    });
    var html = '<ul>';
    items[index].g.forEach(function (group) {
      if (group.core) {
        group.m.forEach(function (m) { html += moduleHtml(group, m); });
        return;
      }
      html += '<li class="sidebar-item sidebar-group' + (openGroups[group.d] ? ' open' : '') + '" data-group="' + escapeHtml(group.d) + '">' +
        '<div class="sidebar-row"><a href="' + escapeHtml(docsRoot + group.d + '/index.html') + '">' + escapeHtml(group.t) + '</a>' +
        '<button type="button" class="chevron" aria-label="Toggle"></button></div><ul>';
      group.m.forEach(function (m) { html += moduleHtml(group, m); });
      html += '</ul></li>';
    });
    html += '</ul>';
    nav.innerHTML = html;
    if (remember) set('sessionStorage', 'fdoc-tab', String(index));
    markActive();
  }

  // Marks the current group/module and attaches the module's function list.
  function markActive() {
    if (!nav) return;
    Array.prototype.forEach.call(nav.querySelectorAll('.sidebar-row.active, a.active'), function (el) { el.classList.remove('active'); });
    var old = nav.querySelector('.sidebar-functions');
    if (old) old.parentNode.removeChild(old);

    if (state.group) {
      var group = nav.querySelector('.sidebar-group[data-group="' + CSS.escape(state.group) + '"]');
      if (group) {
        group.classList.add('open');
        if (!state.module) group.querySelector('.sidebar-row').classList.add('active');
      }
    }
    if (!state.module) return;
    var mod = nav.querySelector('.sidebar-module[data-group="' + CSS.escape(state.group) + '"][data-module="' + CSS.escape(state.module) + '"]');
    if (!mod) return;
    mod.querySelector('.sidebar-row').classList.add('active');
    mod.classList.add('open');

    var template = document.getElementById('module-functions');
    var list = document.createElement('ul');
    list.className = 'sidebar-functions';
    var html = '<li><div class="sidebar-row"><a href="#summary">Summary</a></div></li>';
    if (template) {
      var categories = [];
      Array.prototype.forEach.call(template.content.querySelectorAll('li'), function (li) {
        if (li.classList.contains('sidebar-category')) {
          categories.push({ name: li.textContent, anchor: li.getAttribute('data-anchor'), fns: [] });
        } else if (categories.length) {
          var a = li.querySelector('a');
          categories[categories.length - 1].fns.push({ name: a.textContent, href: a.getAttribute('href'), realm: li.getAttribute('data-realm') });
        }
      });
      categories.forEach(function (c) {
        html += '<li class="sidebar-item open"><div class="sidebar-row"><a href="#' + escapeHtml(c.anchor) + '">' + escapeHtml(c.name) + '</a>' +
          '<button type="button" class="chevron plus" aria-label="Toggle"></button></div><ul>' +
          c.fns.map(function (f) { return '<li><div class="sidebar-row"><a href="' + escapeHtml(f.href) + '">' + realmDot(f.realm) + escapeHtml(f.name) + '</a></div></li>'; }).join('') +
          '</ul></li>';
      });
    }
    list.innerHTML = html;
    mod.appendChild(list);
  }

  function revealActive() {
    if (!nav) return;
    var active = nav.querySelector('.sidebar-row.active');
    if (!active) return;
    var box = active.getBoundingClientRect();
    var frame = nav.getBoundingClientRect();
    if (box.top < frame.top || box.bottom > frame.bottom) {
      nav.scrollTop += box.top - frame.top - frame.height / 3;
    }
  }

  if (nav) {
    nav.addEventListener('click', function (e) {
      var chevron = e.target.closest('.chevron');
      if (chevron) {
        var item = chevron.closest('li');
        item.classList.toggle('open');
        var dir = item.getAttribute('data-group');
        if (dir) {
          if (item.classList.contains('open')) openGroups[dir] = true; else delete openGroups[dir];
          set('sessionStorage', 'fdoc-open-groups', JSON.stringify(openGroups));
        }
        return;
      }
      if (e.target.closest('a') && window.innerWidth <= 900) closeSidebar();
    });
    var ticking = false;
    nav.addEventListener('scroll', function () {
      if (ticking) return;
      ticking = true;
      window.requestAnimationFrame(function () {
        set('sessionStorage', 'fdoc-sidebar-scroll', String(nav.scrollTop));
        ticking = false;
      });
    }, { passive: true });
  }

  renderTabs();
  var initialTab = sectionOf(state.group);
  if (initialTab < 0) initialTab = parseInt(get('sessionStorage', 'fdoc-tab') || '0', 10) || 0;
  showTab(initialTab, false);
  var savedScroll = parseInt(get('sessionStorage', 'fdoc-sidebar-scroll') || '', 10);
  if (nav && !isNaN(savedScroll)) nav.scrollTop = savedScroll;
  revealActive();

  var toggle = document.querySelector('.sidebar-toggle');
  var backdrop = document.querySelector('.sidebar-backdrop');
  function closeSidebar() { body.classList.remove('sidebar-open'); }
  if (toggle) toggle.addEventListener('click', function () { body.classList.toggle('sidebar-open'); });
  if (backdrop) backdrop.addEventListener('click', closeSidebar);

  // In-page navigation ------------------------------------------------------
  // Pages are fetched and only the content column is replaced, so the
  // sidebar keeps its state. Falls back to normal loads when fetch is not
  // available (for example when the files are opened from disk).

  var content = document.getElementById('content-inner');
  var progress = document.getElementById('progress');
  var canSoftNavigate = /^https?:$/.test(window.location.protocol) && typeof window.fetch === 'function' && typeof DOMParser === 'function';

  function sameDocument(url) {
    return url.origin === window.location.origin && url.pathname === window.location.pathname && url.search === window.location.search;
  }

  function scrollToHash(hash) {
    if (hash) {
      var target = document.getElementById(decodeURIComponent(hash.slice(1)));
      if (target) { target.scrollIntoView(); return; }
    }
    window.scrollTo(0, 0);
  }

  function applyPage(doc, url, push) {
    var inner = doc.getElementById('content-inner');
    if (!inner) throw new Error('not a documentation page');
    content.innerHTML = inner.innerHTML;
    document.title = doc.title;
    state.group = doc.body.getAttribute('data-group') || '';
    state.module = doc.body.getAttribute('data-module') || '';
    if (push) window.history.pushState({ fdoc: true }, '', url.href);
    var tab = sectionOf(state.group);
    if (tab >= 0 && tab !== currentTab) showTab(tab, false); else markActive();
    revealActive();
    initPage();
    scrollToHash(url.hash);
    closeSidebar();
  }

  function navigate(url, push) {
    if (progress) { progress.classList.remove('done'); progress.classList.add('active'); }
    content.classList.add('loading');
    fetch(url.href, { credentials: 'same-origin' })
      .then(function (r) { if (!r.ok) throw new Error(r.status); return r.text(); })
      .then(function (html) {
        var doc = new DOMParser().parseFromString(html, 'text/html');
        applyPage(doc, url, push);
        content.classList.remove('loading');
        if (progress) { progress.classList.remove('active'); progress.classList.add('done'); }
      })
      .catch(function () { window.location.href = url.href; });
  }

  if (canSoftNavigate) {
    document.addEventListener('click', function (e) {
      if (e.defaultPrevented || e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return;
      var a = e.target.closest('a[href]');
      if (!a || a.target || a.hasAttribute('download')) return;
      var url = new URL(a.href, window.location.href);
      if (url.origin !== window.location.origin || !/\.html$/.test(url.pathname) || sameDocument(url)) return;
      e.preventDefault();
      navigate(url, true);
    });
    window.addEventListener('popstate', function () {
      navigate(new URL(window.location.href), false);
    });
    window.history.replaceState({ fdoc: true }, '', window.location.href);
  }

  // Search -----------------------------------------------------------------

  var loading = null;
  function loadData(callback) {
    if (window.searchData) return callback();
    if (!loading) {
      loading = [];
      var script = document.createElement('script');
      script.src = docsRoot + 'assets/search_data.js';
      script.onload = function () {
        var waiting = loading;
        loading = null;
        waiting.forEach(function (cb) { cb(); });
      };
      document.head.appendChild(script);
    }
    loading.push(callback);
  }

  function shortName(title) {
    var m = title.match(/([A-Za-z_][A-Za-z0-9_]*)\s*\(/);
    return m ? m[1] : title;
  }

  function score(item, q) {
    var title = item.t.toLowerCase();
    var name = shortName(item.t).toLowerCase();
    var bare = title.replace(/\(.*$/, '');
    if (bare === q || name === q) return 100;
    if (name.indexOf(q) === 0) return 80;
    if (bare.indexOf(q) === 0) return 70;
    var p = bare.indexOf(q);
    if (p >= 0) return 60 - Math.min(p, 20);
    if (q.length >= 3 && item.d && item.d.toLowerCase().indexOf(q) >= 0) return 20;
    return 0;
  }

  function search(query, limit) {
    var q = query.trim().toLowerCase();
    if (!q) return [];
    var results = [];
    var data = window.searchData || [];
    for (var i = 0; i < data.length; i++) {
      var s = score(data[i], q);
      if (s > 0) results.push({ item: data[i], score: s });
    }
    results.sort(function (a, b) {
      if (b.score !== a.score) return b.score - a.score;
      return a.item.t.length - b.item.t.length;
    });
    return results.slice(0, limit).map(function (r) { return r.item; });
  }

  function highlight(text, query) {
    var q = query.trim();
    var idx = q ? text.toLowerCase().indexOf(q.toLowerCase()) : -1;
    if (idx < 0) return escapeHtml(text);
    return escapeHtml(text.slice(0, idx)) + '<mark>' + escapeHtml(text.slice(idx, idx + q.length)) + '</mark>' + escapeHtml(text.slice(idx + q.length));
  }

  var input = document.getElementById('search-input');
  var suggestions = document.getElementById('search-suggestions');
  var selected = -1;

  function hideSuggestions() {
    if (suggestions) { suggestions.hidden = true; suggestions.innerHTML = ''; }
    selected = -1;
  }

  function renderSuggestions() {
    if (!input || !suggestions) return;
    if (!input.value.trim()) { hideSuggestions(); return; }
    if (!window.searchData) { loadData(renderSuggestions); return; }
    var results = search(input.value, 10);
    selected = -1;
    if (!results.length) { hideSuggestions(); return; }
    suggestions.innerHTML = results.map(function (r) {
      return '<li><a href="' + escapeHtml(docsRoot + r.r) + '">' +
        '<span class="suggestion-kind">' + realmPill(r.rl) + escapeHtml(r.k) + '</span>' +
        '<span class="suggestion-title">' + highlight(r.t, input.value) + '</span></a></li>';
    }).join('');
    suggestions.hidden = false;
  }

  function moveSelection(delta) {
    var rows = suggestions.querySelectorAll('li');
    if (!rows.length) return;
    if (selected >= 0) rows[selected].classList.remove('selected');
    selected = (selected + delta + rows.length) % rows.length;
    rows[selected].classList.add('selected');
  }

  if (input) {
    input.addEventListener('input', renderSuggestions);
    input.addEventListener('focus', function () { loadData(function () {}); renderSuggestions(); });
    input.addEventListener('keydown', function (e) {
      if (e.key === 'ArrowDown') { e.preventDefault(); moveSelection(1); }
      else if (e.key === 'ArrowUp') { e.preventDefault(); moveSelection(-1); }
      else if (e.key === 'Escape') { hideSuggestions(); input.blur(); }
      else if (e.key === 'Enter' && selected >= 0) {
        e.preventDefault();
        var a = suggestions.querySelectorAll('li a')[selected];
        if (a) a.click();
      }
    });
    input.form.addEventListener('submit', function (e) {
      if (!canSoftNavigate) return;
      e.preventDefault();
      hideSuggestions();
      navigate(new URL(docsRoot + 'search.html?q=' + encodeURIComponent(input.value)), true);
    });
    document.addEventListener('click', function (e) {
      if (suggestions && !suggestions.contains(e.target) && e.target !== input) hideSuggestions();
      else if (suggestions && suggestions.contains(e.target)) hideSuggestions();
    });
    document.addEventListener('keydown', function (e) {
      var tag = (document.activeElement && document.activeElement.tagName) || '';
      if (e.key === '/' && tag !== 'INPUT' && tag !== 'TEXTAREA') {
        e.preventDefault();
        input.focus();
        input.select();
      }
    });
  }

  // Per-page setup, run on load and after each in-page navigation.
  function initPage() {
    var resultsEl = document.getElementById('search-results');
    if (!resultsEl) return;
    var query = new URLSearchParams(window.location.search).get('q') || '';
    var status = document.getElementById('search-status');
    if (input) input.value = query;
    if (!query) return;
    loadData(function () {
      var results = search(query, 100);
      if (status) status.textContent = results.length + ' result' + (results.length === 1 ? '' : 's') + ' for "' + query + '"';
      resultsEl.innerHTML = results.map(function (r) {
        return '<div class="result">' +
          '<a class="result-title" href="' + escapeHtml(docsRoot + r.r) + '">' + highlight(r.t, query) + '</a>' +
          '<div class="result-meta">' + escapeHtml(r.k) + realmPill(r.rl) + (r.g ? ' · ' + escapeHtml(r.g) : '') + '</div>' +
          (r.d ? '<p class="result-desc">' + highlight(r.d, query) + '</p>' : '') +
          '</div>';
      }).join('');
    });
  }
  initPage();
})();
